package com.example.library; import org.springframework.boot.*;import org.springframework.boot.autoconfigure.SpringBootApplication;import org.springframework.web.bind.annotation.*;import java.util.*;
@SpringBootApplication @RestController public class LibraryApplication { List<Map<String,Object>> books=new ArrayList<>(); public static void main(String[]a){SpringApplication.run(LibraryApplication.class,a);} @GetMapping("/api/books") List<Map<String,Object>> all(){return books;} @PostMapping("/api/books") Map<String,Object> add(@RequestBody Map<String,Object>b){b.put("id",books.size()+1);b.putIfAbsent("available",true);books.add(b);return b;} }
